begin;
do $$
declare a uuid:=gen_random_uuid(); o uuid:=gen_random_uuid(); e uuid:=gen_random_uuid(); u uuid; u2 uuid; modulo uuid; c uuid; p uuid; m uuid; r uuid; x jsonb; f uuid:=gen_random_uuid();
begin
 insert into auth.users(id,email) values(a,a||'@reverse.test'),(o,o||'@reverse.test');
 insert into public.perfis(id,nome,role,ativo) values(a,'Admin teste','bdl_admin',true),(o,'Operador teste','municipal_user',true);
 insert into public.empresas(id,nome,status) values(e,'Estorno teste','active');
 select id into modulo from public.modulos where slug='gestao-estabelecimentos';
 insert into public.licencas(prefeitura_id,modulo_id,status,inicio,fim,valor_anual) values(e,modulo,'active',current_date-1,current_date+1,0);
 select id into u from public.gestao_unidades where empresa_id=e;
 insert into public.gestao_unidades(empresa_id,nome) values(e,'Outra unidade') returning id into u2;
 update public.perfis set prefeitura_id=e where id=o;
 perform public.atualizar_usuario_acessos(a,o,e,array[modulo],array[]::uuid[]);
 select id into c from public.gestao_categorias where empresa_id=e limit 1;
 p:=public.gestao_operar(a,'produto',jsonb_build_object('unidade_id',u,'nome','Produto teste','categoria_id',c,'unidade','un','minimo',0));
 x:=jsonb_build_object('unidade_id',u,'produto_id',p,'tipo','entrada','quantidade',10,'motivo','Compra original','custo_unitario','3.25');
 perform public.gestao_operar(a,'movimento',x);
 select id into m from public.gestao_movimentos where produto_id=p and tipo='entrada';
 begin perform public.gestao_estornar_movimento(o,u,m,'Operador sem permissão');raise exception 'FAIL operator';exception when raise_exception then if sqlerrm not like '%exige acesso de gestor%' then raise;end if;end;
 begin perform public.gestao_estornar_movimento(a,u2,m,'Unidade errada');raise exception 'FAIL unit';exception when raise_exception then if sqlerrm not like '%não encontrada%' then raise;end if;end;
 begin perform public.gestao_estornar_movimento(a,u,m,' ');raise exception 'FAIL reason';exception when raise_exception then if sqlerrm not like '%justificativa%' then raise;end if;end;
 r:=public.gestao_estornar_movimento(a,u,m,'Compra duplicada');
 if public.gestao_estornar_movimento(a,u,m,'Nova tentativa')<>r then raise exception 'FAIL idempotency';end if;
 if (select saldo from public.gestao_produtos where id=p)<>0 or (select count(*) from public.gestao_movimentos where estorno_de=m)<>1 then raise exception 'FAIL duplicate stock';end if;
 if not exists(select 1 from public.gestao_movimentos where id=r and quantidade=-10 and custo_unitario=3.25 and custo_total=-32.50 and criado_por=a) then raise exception 'FAIL reversal cost';end if;
 if not exists(select 1 from public.gestao_movimentos where id=m and quantidade=10 and custo_total=32.50 and estornado_por=a and estornado_em is not null) then raise exception 'FAIL preserved original';end if;
 if not exists(select 1 from public.gestao_auditoria where registro_id=r and acao='estornar_movimento') then raise exception 'FAIL audit';end if;
 begin perform public.gestao_estornar_movimento(a,u,r,'Estorno do estorno');raise exception 'FAIL reverse reversal';exception when raise_exception then if sqlerrm not like '%Somente movimentações manuais%' then raise;end if;end;
 perform public.gestao_operar(a,'movimento',x||'{"motivo":"Nova compra"}');
 select id into m from public.gestao_movimentos where produto_id=p and motivo='Nova compra';
 perform public.gestao_operar(a,'movimento',x||'{"tipo":"perda","quantidade":2,"custo_unitario":"","motivo":"Quebra teste"}');
 begin perform public.gestao_estornar_movimento(a,u,m,'Compra errada');raise exception 'FAIL negative stock';exception when raise_exception then if sqlerrm not like '%estoque negativo%' then raise;end if;end;
 if exists(select 1 from public.gestao_movimentos where estorno_de=m) or (select saldo from public.gestao_produtos where id=p)<>8 then raise exception 'FAIL failed reversal atomicity';end if;
 select id into r from public.gestao_movimentos where produto_id=p and tipo='perda';
 perform public.gestao_estornar_movimento(a,u,r,'Perda errada');
 perform public.gestao_estornar_movimento(a,u,m,'Compra errada');
 if (select saldo from public.gestao_produtos where id=p)<>0 then raise exception 'FAIL loss reversal';end if;
 perform public.gestao_operar(a,'movimento',x||'{"tipo":"ajuste","quantidade":-3,"custo_unitario":"","motivo":"Ajuste teste"}');
 select id into m from public.gestao_movimentos where produto_id=p and tipo='ajuste';
 perform public.gestao_estornar_movimento(a,u,m,'Ajuste errado');
 if (select saldo from public.gestao_produtos where id=p)<>0 then raise exception 'FAIL negative adjustment';end if;
 perform public.gestao_operar(a,'salvar',jsonb_build_object('id',f,'versao',0,'unidade_id',u,'data',current_date,'turno','dia','origem','teste','itens',jsonb_build_array(jsonb_build_object('produto_id',p,'quantidade',1,'total',5)),'pagamentos',jsonb_build_array(jsonb_build_object('forma','Pix','origem','Conta','valor',5))));
 perform public.gestao_operar(a,'confirmar',jsonb_build_object('id',f,'versao',1,'unidade_id',u));
 select id into m from public.gestao_movimentos where produto_id=p and tipo='venda';
 begin perform public.gestao_estornar_movimento(a,u,m,'Venda errada');raise exception 'FAIL closing';exception when raise_exception then if sqlerrm not like '%reabra o fechamento%' then raise;end if;end;
 if has_function_privilege('authenticated','public.gestao_estornar_movimento(uuid,uuid,uuid,text)','execute') or has_function_privilege('anon','public.gestao_estornar_movimento(uuid,uuid,uuid,text)','execute') then raise exception 'FAIL RPC grants';end if;
end $$;
select 'PASS: role/unit/reason, idempotency, signed costs, original/audit, no reverse reversal, negative stock atomicity, loss/adjustment, protected closing, grants' result;
rollback;

